/**
 * Chart.js adapter (integration.md I2 — Q22: the FIRST framework adapter). Registers a custom
 * controller `type: "hangingStringsDiagram"` that mounts the embeddable façade (I1/I4) as a DOM
 * overlay inside the chart's container: Chart.js keeps its lifecycle (config, `update()`,
 * `destroy()`, responsive container), Hanging Strings Diagram keeps its own SVG rendering and
 * interactions. Per I1 the adapter NEVER reaches into renderers — every call goes through
 * `createHangingStringsDiagram`.
 *
 * Data mapping (I3: the adapter owns it, the façade sees only the canonical shape):
 *   - `data.labels[i]`               → category id + name
 *   - `data.datasets[0].data[i]`     → value (null/NaN entries are skipped, Chart.js's own
 *                                      missing-data convention)
 *   - `data.datasets[1].data[i]`     → optional secondaryValue (knob size / heat-map, D7/D8)
 *   - `data.datasets[0].hsdGroupIds[i]` → optional per-category group id; group colors/names
 *                                      come from `options.hangingStringsDiagram.groups`, else are
 *                                      derived from the dataset's backgroundColor/label.
 * Hierarchy (D16) has no Chart.js analog — pass full canonical `categories` (with children)
 * via `options.hangingStringsDiagram.categories` to bypass the mapping entirely.
 *
 * Everything else the façade accepts (railMode, theme, backdrop, callbacks, …) rides in
 * `options.hangingStringsDiagram` and is re-diffed on every `chart.update()`.
 */

import { DatasetController, PointElement } from "chart.js";
import type { Chart, UpdateMode } from "chart.js";
// The adapter consumes the library through its PUBLIC bare specifier (I1: adapters never
// reach into internals). Dev server + vitest alias it to src/index.ts (vite.config.ts);
// tsconfig `paths` does the same for the compiler; the adapter build keeps it external.
import {
  createHangingStringsDiagram,
  type HangingStringsDiagram,
  type HangingStringsDiagramOptions,
  type HangingStringCategory,
  type HangingStringGroup,
} from "hanging-strings-diagram";

/** `options.hangingStringsDiagram`: everything the façade accepts, with data optional — categories/
 * groups given here OVERRIDE the Chart.js data mapping (the hierarchy path). */
export type HangingStringsDiagramChartConfig = Partial<HangingStringsDiagramOptions>;

declare module "chart.js" {
  interface ChartTypeRegistry {
    hangingStringsDiagram: {
      chartOptions: { hangingStringsDiagram?: HangingStringsDiagramChartConfig };
      datasetOptions: { hsdGroupIds?: string[] };
      defaultDataPoint: number | null;
      metaExtensions: object;
      parsedDataType: number;
      scales: never;
    };
  }
}

/** Fallback group id when the data declares none — one implicit group for the whole chart. */
const IMPLICIT_GROUP_ID = "all";
const FALLBACK_COLOR = "#6b7c93";

/** The minimal slice of Chart.js `data` the mapper reads — structurally typed so the mapper
 * stays pure and unit-testable without a Chart instance. */
export interface ChartJsLikeData {
  labels?: unknown[];
  datasets?: {
    label?: string;
    data?: unknown[];
    backgroundColor?: unknown;
    /** Adapter extension: per-index group id, aligned with `labels`. */
    hsdGroupIds?: string[];
  }[];
}

/**
 * Pure mapper: Chart.js `labels` + `datasets` → the canonical Hanging Strings Diagram data shape.
 * `declaredGroups` (from `options.hangingStringsDiagram.groups`) wins for group names/colors; groups
 * only referenced by the data are derived with the dataset's backgroundColor as their color.
 */
export function chartDataToHangingStringsDiagram(
  data: ChartJsLikeData,
  declaredGroups?: HangingStringGroup[]
): { categories: HangingStringCategory[]; groups: HangingStringGroup[] } {
  const labels = data.labels ?? [];
  const primary = data.datasets?.[0];
  const secondary = data.datasets?.[1];

  const categories: HangingStringCategory[] = [];
  const seenGroupIds: string[] = [];
  for (let i = 0; i < labels.length; i++) {
    const value = Number(primary?.data?.[i]);
    if (primary?.data?.[i] == null || !Number.isFinite(value)) continue; // missing point
    const groupId = primary?.hsdGroupIds?.[i] ?? IMPLICIT_GROUP_ID;
    if (!seenGroupIds.includes(groupId)) seenGroupIds.push(groupId);
    const secondaryRaw = secondary?.data?.[i];
    const secondaryValue = Number(secondaryRaw);
    categories.push({
      id: String(labels[i]),
      name: String(labels[i]),
      value,
      groupId,
      ...(secondaryRaw != null && Number.isFinite(secondaryValue) ? { secondaryValue } : {}),
    });
  }

  const declaredById = new Map((declaredGroups ?? []).map((g) => [g.id, g]));
  const bg = primary?.backgroundColor;
  const colorAt = (index: number): string =>
    typeof bg === "string" ? bg : Array.isArray(bg) && typeof bg[index] === "string" ? bg[index] : FALLBACK_COLOR;
  const groups: HangingStringGroup[] = seenGroupIds.map((id) => {
    const declared = declaredById.get(id);
    if (declared) return declared;
    const firstIndex = categories.findIndex((c) => c.groupId === id);
    return {
      id,
      name: id === IMPLICIT_GROUP_ID ? primary?.label ?? "Values" : id,
      color: colorAt(firstIndex),
    };
  });
  // Declared groups the data doesn't reference yet still belong in the legend contract.
  for (const g of declaredGroups ?? []) {
    if (!groups.some((existing) => existing.id === g.id)) groups.push(g);
  }
  return { categories, groups };
}

/** Per-chart adapter state — instance + the option values already applied (diffing keeps
 * `chart.update()` cheap and idempotent). */
interface AdapterState {
  instance: HangingStringsDiagram;
  host: HTMLElement;
  applied: HangingStringsDiagramChartConfig;
}

const stateByChart = new WeakMap<Chart, AdapterState>();

function configOf(chart: Chart): HangingStringsDiagramChartConfig {
  return (chart.options as { hangingStringsDiagram?: HangingStringsDiagramChartConfig }).hangingStringsDiagram ?? {};
}

function resolveData(chart: Chart, config: HangingStringsDiagramChartConfig) {
  // Canonical categories in the options bypass the mapping (the hierarchy path, see module
  // note); groups may still come from either place.
  if (config.categories) {
    return { categories: config.categories, groups: config.groups ?? [] };
  }
  return chartDataToHangingStringsDiagram(chart.data as ChartJsLikeData, config.groups);
}

/** The DOM overlay the façade mounts into — absolutely positioned over the chart's canvas
 * inside the container div Chart.js already requires for responsive sizing. */
function ensureHost(chart: Chart): HTMLElement {
  const parent = chart.canvas.parentElement;
  if (!parent) throw new Error("hangingStringsDiagram: the chart canvas needs a container element");
  if (getComputedStyle(parent).position === "static") parent.style.position = "relative";
  const host = document.createElement("div");
  host.style.position = "absolute";
  host.style.inset = "0";
  host.style.overflow = "hidden";
  parent.appendChild(host);
  return host;
}

export class HangingStringsDiagramController extends DatasetController {
  static readonly id = "hangingStringsDiagram";
  /** No canvas elements are ever CREATED (buildOrUpdateElements is a no-op) — but Chart.js
   * resolves `dataElementType` through its element registry unconditionally (only
   * `datasetElementType` may be false), so a real registered element name must stand in.
   * registerHangingStringsDiagram registers PointElement to guarantee it resolves. */
  static readonly defaults = {
    dataElementType: "point",
    datasetElementType: false,
  };
  /** Chart.js chrome that presumes canvas-drawn data is switched off; the overlay owns
   * pointer interactions, its own legend semantics (group swatches), and its own hover card
   * (or the host's, via onHover/showHoverCard). */
  static readonly overrides = {
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false },
    },
    scales: {},
  };

  // The chart has no cartesian scales and no parsed elements — skip that machinery whole.
  linkScales(): void {}
  parse(): void {}
  buildOrUpdateElements(): void {}
  draw(): void {}

  update(_mode: UpdateMode): void {
    // One façade instance per CHART — dataset 1 (the optional secondary metric) gets its own
    // controller from Chart.js, which must not mount a second chart.
    if (this.index !== 0) return;
    const chart = this.chart;
    const config = configOf(chart);
    const { categories, groups } = resolveData(chart, config);

    let state = stateByChart.get(chart);
    if (!state) {
      const host = ensureHost(chart);
      const instance = createHangingStringsDiagram(host, {
        ...config,
        categories,
        groups,
        height: config.height ?? chart.height,
      });
      state = { instance, host, applied: { ...config } };
      stateByChart.set(chart, state);
      return;
    }

    // Live option diffing: chart.update() after mutating options.hangingStringsDiagram applies just
    // what changed, through the façade's own setters.
    const { instance, applied } = state;
    if (config.railMode && config.railMode !== applied.railMode) instance.setRailMode(config.railMode);
    if (config.theme !== undefined && config.theme !== applied.theme) instance.setTheme(config.theme);
    if (config.threadTexture !== applied.threadTexture) {
      instance.setThreadTexture(config.threadTexture ?? null);
    }
    if (config.backdrop && config.backdrop !== applied.backdrop) instance.setBackdrop(config.backdrop);
    const display: Record<string, unknown> = {};
    for (const key of [
      "colorMode",
      "knobEncodesSecondMetric",
      "showTicks",
      "tickTarget",
      "labelValues",
      "stiffness",
    ] as const) {
      if (config[key] !== undefined && config[key] !== applied[key]) display[key] = config[key];
    }
    if (Object.keys(display).length > 0) instance.setOptions(display);
    state.applied = { ...config };

    instance.update({ categories, groups });
  }
}

/** Teardown rides a plugin (afterDestroy is a stable, documented hook — controller-internal
 * destroy paths are not): the façade instance and its overlay leave with the chart. */
export const hangingStringsDiagramCleanupPlugin = {
  id: "hangingStringsDiagramCleanup",
  afterDestroy(chart: Chart): void {
    const state = stateByChart.get(chart);
    if (!state) return;
    state.instance.destroy();
    state.host.remove();
    stateByChart.delete(chart);
  },
};

/** One-call registration: `registerHangingStringsDiagram(Chart)` — then `new Chart(ctx, { type:
 * "hangingStringsDiagram", … })`. */
export function registerHangingStringsDiagram(chartjs: {
  register: (...items: unknown[]) => void;
}): void {
  // PointElement backs the controller's (never-instantiated) dataElementType — registered
  // here so tree-shaken chart.js setups don't need to know about the stand-in.
  chartjs.register(HangingStringsDiagramController, hangingStringsDiagramCleanupPlugin, PointElement);
}
